window.SurveyPresetsApi = {
  getConfigKey(voltage, phase) {
    if (!voltage || !phase) return null;
    return `${voltage}${phase}`;
  },
  getConfig(voltage, phase) {
    const key = this.getConfigKey(voltage, phase);
    return key ? window.SURVEY_PRESETS.configs[key] || null : null;
  },
  getSet(setId) {
    return window.SURVEY_PRESETS.sets[String(setId)] || null;
  },
  getSetOptions(setIds) {
    return (setIds || []).map(id => window.SURVEY_PRESETS.sets[id]).filter(Boolean);
  },
  getCableOptions(config, sectionKey) {
    if (!config) return [];
    const ids = config[sectionKey]?.cableIds || [];
    const pool = config.voltage === "lv" ? window.SURVEY_PRESETS.lvCables : window.SURVEY_PRESETS.mvCables;
    return pool.filter(c => ids.includes(c.id));
  },
  formatSetLabel(setObj) {
    return setObj ? `${setObj.id}\t${setObj.name}` : "";
  },
  formatCableLabel(item) {
    return item ? `${item.id}\t${item.name}` : "";
  },
  getSpecialPoleRules(configKey) {
    return window.SURVEY_PRESETS.specialPoleRules?.[configKey] || null;
  },
  getSpecialPoleRule(configKey, kind) {
    const rules = this.getSpecialPoleRules(configKey);
    return rules?.[kind] || null;
  },
  getTrInstallCatalog() {
    return window.SURVEY_PRESETS.trInstallCatalog || null;
  },
  getTransformers(phase) {
    const list = window.SURVEY_PRESETS.transformers || [];
    return phase ? list.filter(t => t.phase === phase) : list;
  },
  getTrSetOptions(installType, phase) {
    const catalog = this.getTrInstallCatalog();
    if (!catalog || !installType || !phase) return [];
    const group = catalog[installType]?.[phase];
    return this.getSetOptions(group?.setIds || []);
  },
  expandTrSetItems(setId, options = {}) {
    const setObj = this.getSet(setId);
    if (!setObj) return [];
    const skip = options.isExistingHost ? (setObj.skipOnExistingHost || []) : [];
    return setObj.items.filter(item => !skip.includes(item.id));
  }
};
